import{_ as a,o,c as e,ai as s}from"./chunks/framework.BBSijY9B.js";const m=JSON.parse('{"title":"技能沉淀","description":"把做顺了的流程保存成技能，让所有 Bot 都能按同一套方法稳定复用。","frontmatter":{"related":["/automation/routines","/automation/multi-bot-teamwork","/templates/inbox-manager"],"title":"技能沉淀","description":"把做顺了的流程保存成技能，让所有 Bot 都能按同一套方法稳定复用。","section":"automation","order":2,"tags":["自动化","技能","流程","复用"],"sources":["https://docs.x.ai/grok-bot/skills-routines-and-automations","https://cursor.com/docs/grok-bot/work"],"wordCount":547,"readingTime":1,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"技能沉淀 | 王宇宙 | WANGXXXL"}],["meta",{"property":"og:description","content":"把做顺了的流程保存成技能，让所有 Bot 都能按同一套方法稳定复用。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/automation/skills"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/automation-skills-4073bda1f7.png"}],["meta",{"property":"og:image:alt","content":"技能沉淀 · 王宇宙 | WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"技能沉淀 | 王宇宙 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"把做顺了的流程保存成技能，让所有 Bot 都能按同一套方法稳定复用。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/automation-skills-4073bda1f7.png"}],["meta",{"name":"twitter:image:alt","content":"技能沉淀 · 王宇宙 | WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/automation/skills"}]]},"headers":[],"relativePath":"automation/skills.md","filePath":"automation/skills.md","lastUpdated":1792485206000}'),n={name:"automation/skills.md"};function i(l,t,p,r,c,d){return o(),e("div",null,[...t[0]||(t[0]=[s(`<h1 id="技能沉淀" tabindex="-1">技能沉淀 <a class="header-anchor" href="#技能沉淀" aria-label="Permalink to &quot;技能沉淀&quot;">​</a></h1><p>你和 Bot 一起把一件事做顺了，比如&quot;每周整理客户反馈&quot;，用了三轮修改才达到你满意的样子。如果下周还要重新交代一遍，就太浪费了。<strong>技能</strong>就是把这套做法存下来，下次一句话调用。</p><h2 id="技能和例程的区别" tabindex="-1">技能和例程的区别 <a class="header-anchor" href="#技能和例程的区别" aria-label="Permalink to &quot;技能和例程的区别&quot;">​</a></h2><ul><li><strong>技能</strong>说的是&quot;<strong>怎么做</strong>&quot;：步骤、判断标准、输出格式、哪里要停。</li><li><strong>例程</strong>说的是&quot;<strong>什么时候做</strong>&quot;：定时或事件触发。</li></ul><p>两者经常搭配：先有技能，再让例程定时调用它。技能是你名下所有 Bot 共享的一个库，任何 Bot 都能用（前提是它有对应的连接器或登录）。</p><h2 id="怎么存" tabindex="-1">怎么存 <a class="header-anchor" href="#怎么存" aria-label="Permalink to &quot;怎么存&quot;">​</a></h2><p>做完一次满意的任务后，直接说：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把我们刚才的流程保存成一个技能，叫&quot;每周客户反馈整理&quot;。</span></span>
<span class="line"><span>包括：数据来源（邮箱标签&quot;反馈&quot;和表单后台）、分类标准（功能建议/故障/表扬/其他）、</span></span>
<span class="line"><span>输出格式（表格 + 前三大问题总结）、以及&quot;不得直接回复客户&quot;这条规则。</span></span></code></pre></div><h2 id="一个好技能应该写清楚" tabindex="-1">一个好技能应该写清楚 <a class="header-anchor" href="#一个好技能应该写清楚" aria-label="Permalink to &quot;一个好技能应该写清楚&quot;">​</a></h2><ol><li>什么时候用；</li><li>需要哪些输入和权限；</li><li>按什么顺序做；</li><li>怎么检查结果对不对；</li><li>最后交付什么；</li><li>哪些动作需要审批。</li></ol><p>存好后可以让它念给你听，查漏补缺：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把&quot;每周客户反馈整理&quot;这个技能的完整内容给我看看。</span></span>
<span class="line"><span>补充一条：如果某条反馈涉及退款，单独标红并放在最前面。</span></span></code></pre></div><h2 id="用演示来教" tabindex="-1">用演示来教 <a class="header-anchor" href="#用演示来教" aria-label="Permalink to &quot;用演示来教&quot;">​</a></h2><p>部分账号可以使用&quot;演示教学&quot;功能：打开电脑画面，选择教学，然后你亲手在浏览器里操作一遍，Bot 会据此生成一份技能草稿。录制有时长上限，不录麦克风；演示时别暴露密码。生成的只是草稿，记得补上判断规则、异常处理和审批边界，并用安全的数据测试一次。</p><p>如果你看不到这个功能，就用文字描述加一次完整的任务来生成技能，效果一样好。该功能是否可用以官方最新说明为准。</p><h2 id="调用技能" tabindex="-1">调用技能 <a class="header-anchor" href="#调用技能" aria-label="Permalink to &quot;调用技能&quot;">​</a></h2><p>在输入框里打 <code>/</code>，就能选择已保存的技能：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/每周客户反馈整理 这次只看 10 月 1 日到 10 月 15 日的数据。</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">先从&quot;小而稳&quot;的技能开始</p><p>第一个技能最好是你每周都做、步骤固定、错了也不会出大事的流程。跑顺之后再挑战复杂的。</p></div><div class="warning custom-block"><p class="custom-block-title">技能会被分享时</p><p>如果你把 Bot 分享给别人，技能内容也会随配置一起被复制。技能里不要写 API 密钥、内部网址和客户数据。</p></div>`,20)])])}const h=a(n,[["render",i]]);export{m as __pageData,h as default};
